SELECT 'rm-1798', NULL, 'ROADMAP-BUILT-VERIFY-1: roadmap item PLUS-3 (id 1798) is built, deployed or implemented and waits for its closing probe', 'PLUS-3 plus step: fleet_tasks management-personas-plus (enabled) holds pl-research and pl-brief, plus_ledger holds the proposal it filed for jobs (proposal #2152, issue 1001801), and the task''s latest run finished ok. The step had been failing on a plus_ledger CHECK constraint since 2026-11-04T21:52Z until PLUS-LEDGER-STATUS-1 rebuilt the table', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM fleet_tasks WHERE id = ''management-personas-plus'' AND enabled = 1 AND instr(definition, ''pl-research'') > 0 AND instr(definition, ''pl-brief'') > 0) = 1 AND (SELECT COUNT(*) FROM plus_ledger WHERE evidence LIKE ''proposal #%'') >= 1 AND (SELECT status FROM fleet_runs WHERE task_id = ''management-personas-plus'' ORDER BY id DESC LIMIT 1) = ''ok'' THEN ''ok'' ELSE ''the plus task is missing a step, has filed no proposal, or its latest run did not finish ok'' END AS observed', 'd1-query', 48, 'qnfo-github-steward', 1, 'active', 'roadmap-dod-v1', datetime('now')
FROM roadmap_implementation WHERE id = 1798 AND item = 'PLUS-3' AND status IN ('built', 'deployed', 'implemented');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
SELECT 'rm-1799', NULL, 'ROADMAP-BUILT-VERIFY-1: roadmap item PLUS-4 (id 1799) is built, deployed or implemented and waits for its closing probe', 'PLUS-4 verify-and-keep: management-personas-plus holds pl-outcome-baseline, pl-outcome-review, pl-outcome-result and pl-revert-request, plus_ledger admits the deployed, kept and reverted statuses they write, plus_shipped_7d and plus_kept_share_30d have enabled triggers, and the latest run finished ok. Not yet exercised on a live plus: none has completed its seven-day check, which plus_kept_share_30d measures when one does', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM fleet_tasks WHERE id = ''management-personas-plus'' AND enabled = 1 AND instr(definition, ''pl-outcome-baseline'') > 0 AND instr(definition, ''pl-outcome-review'') > 0 AND instr(definition, ''pl-outcome-result'') > 0 AND instr(definition, ''pl-revert-request'') > 0) = 1 AND (SELECT COUNT(*) FROM analytics_metric_triggers WHERE metric_key IN (''plus_shipped_7d'', ''plus_kept_share_30d'') AND enabled = 1) = 2 AND (SELECT COUNT(*) FROM sqlite_master WHERE name = ''plus_ledger'' AND instr(sql, ''deployed'') > 0) = 1 AND (SELECT status FROM fleet_runs WHERE task_id = ''management-personas-plus'' ORDER BY id DESC LIMIT 1) = ''ok'' THEN ''ok'' ELSE ''the verify-and-keep steps, their two triggers, the deployed/kept/reverted statuses or a healthy latest run are missing'' END AS observed', 'd1-query', 48, 'qnfo-github-steward', 1, 'active', 'roadmap-dod-v1', datetime('now')
FROM roadmap_implementation WHERE id = 1799 AND item = 'PLUS-4' AND status IN ('built', 'deployed', 'implemented');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
SELECT 'rm-1801', NULL, 'ROADMAP-BUILT-VERIFY-1: roadmap item PLUS-6 (id 1801) is built, deployed or implemented and waits for its closing probe', 'PLUS-6 plus-the-plus: the pl-deployed step of management-personas-plus carries the rest-after-three-misses (rest_until, misses_in_row) and simplify-every-fifth-cycle (pluses_since_simplify) logic, product_registry has the counters on all 9 products, migrations/2026-11-01-plussing-6.sql is recorded ok (id 985), and the latest run finished ok. Not yet exercised on a live plus (see PLUS-4)', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM fleet_tasks WHERE id = ''management-personas-plus'' AND enabled = 1 AND instr(definition, ''rest_until'') > 0 AND instr(definition, ''misses_in_row'') > 0 AND instr(definition, ''pluses_since_simplify'') > 0) = 1 AND (SELECT COUNT(*) FROM product_registry WHERE misses_in_row >= 0 AND pluses_since_simplify >= 0) >= 8 AND (SELECT COUNT(*) FROM sqlite_master WHERE name = ''plus_ledger'' AND instr(sql, ''deployed'') > 0) = 1 AND (SELECT status FROM fleet_runs WHERE task_id = ''management-personas-plus'' ORDER BY id DESC LIMIT 1) = ''ok'' THEN ''ok'' ELSE ''the rest and simplify logic, the product_registry counters, the deployed status or a healthy latest run are missing'' END AS observed', 'd1-query', 48, 'qnfo-github-steward', 1, 'active', 'roadmap-dod-v1', datetime('now')
FROM roadmap_implementation WHERE id = 1801 AND item = 'PLUS-6' AND status IN ('built', 'deployed', 'implemented');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
SELECT 'rm-3108', NULL, 'ROADMAP-BUILT-VERIFY-1: roadmap item YT-15 (id 3108) is built, deployed or implemented and waits for its closing probe', 'YT-15 paper pages: PR 7216 (315c6f3f) is on main and GET https://papers.qnfo.org/api/paper-videos returns count 4 with a youtube-nocookie embed per Short and the paper page it belongs to (read 2026-11-05)', '{"url": "https://papers.qnfo.org/api/paper-videos", "status": 200, "contains": "youtube-nocookie.com/embed/"}', 'runner-https', 48, 'qnfo-github-steward', 1, 'active', 'roadmap-dod-v1', datetime('now')
FROM roadmap_implementation WHERE id = 3108 AND item = 'YT-15' AND status IN ('built', 'deployed', 'implemented');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
SELECT 'rm-3110', NULL, 'ROADMAP-BUILT-VERIFY-1: roadmap item YT-17 (id 3110) is built, deployed or implemented and waits for its closing probe', 'YT-17 interest ranking: PR 7244 (e0c0a946) is on main; rankByInterest (ext_30d then pv_30d from paper_readership) is wired into the candidate list in qnfo-youtube-shorts and unit-tested; the live proof is the first first-time Short started after the ranking shipped (a YT-UPGRADE-1 remake is ordered before ranked papers by design: the first Short started after the merge, id 5 at 2026-11-04T23:00Z, was the remake of the oldest Short), and paper_readership holds 868 rows to rank by', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM youtube_videos v WHERE v.created_at >= ''2026-11-04T22:00:00Z'' AND NOT EXISTS (SELECT 1 FROM youtube_videos o WHERE o.slug = v.slug || ''@v1'')) >= 1 AND (SELECT COUNT(*) FROM paper_readership WHERE slug IS NOT NULL) >= 1 THEN ''ok'' ELSE ''pending: no first-time Short (one that is not a YT-UPGRADE-1 remake, which are ordered before ranked papers) has started since qnfo-youtube-shorts 0.5.1 shipped the readership ranking at about 2026-11-04T21:40Z'' END AS observed', 'd1-query', 48, 'qnfo-github-steward', 1, 'active', 'roadmap-dod-v1', datetime('now')
FROM roadmap_implementation WHERE id = 3110 AND item = 'YT-17' AND status IN ('built', 'deployed', 'implemented');

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('roadmap-built-unverified', 'a roadmap item sits at built, deployed or implemented with no closing probe, so its GitHub mirror stays open for ever',
  'no loop verifies an item a session marks built: roadmap-self-maintain handles GL-, NEXT-, PROJ- and FM- rows and the steward only the metric-breach rows (24 mirrors open 4 to 8 days on 2026-11-04)',
  'register the item closing probe as a remediation contract rm-<roadmap id> (module roadmap-dod-v1) in the migration that marks it built; qnfo-github-steward psBuiltVerify verifies the item when the probe passes and the mirror closes',
  'the fm-roadmap-built-unverified contract counts built, deployed and implemented roadmap rows older than 3 days whose GitHub mirror is open and that have no active or holding rm- contract, expected 0',
  'fm-roadmap-built-unverified', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL,
  'a roadmap_implementation row at built, deployed or implemented created more than 3 days ago, mirrored as an open GitHub issue, whose class rm-<id> has no active or holding remediation contract',
  'open roadmap mirrors on GitHub whose code is merged; roadmap items that never reach verified',
  'roadmap and the GitHub mirror: finished work reads as open');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-roadmap-built-unverified', NULL, 'ROADMAP-BUILT-VERIFY-1', 'failure-mode detector',
  'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM roadmap_implementation r WHERE r.status IN (''built'', ''deployed'', ''implemented'') AND r.created_at < datetime(''now'', ''-3 days'') AND EXISTS (SELECT 1 FROM roadmap_gh_links g WHERE g.roadmap_id = r.id AND g.gh_state = ''open'') AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = ''rm-'' || r.id AND c.status IN (''active'', ''holding''))) AS TEXT) AS observed',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now'));

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'A-roadmap-done (remediation sweep 2026-11-04)',
  'a built roadmap item is finished work whose only missing step is a closing probe; the steward already closes the mirror when D1 says verified',
  'ROADMAP-BUILT-VERIFY-1: 24 rm- contracts with live-read probes; steward 0.16.0 verifies built items on a passing contract; fm-roadmap-built-unverified detector',
  'live reads 2026-11-05: 24 built/deployed/implemented rows with open mirrors; psRoadmap closes only verified rows; no loop moves built to verified; 22 probes pass at birth, PLUS-3/4/6 wait on PLUS-LEDGER-STATUS-1, YT-17 on the next Short',
  'migration merged', '24 remediation_contracts rows, one failure mode and its detector, one decision_log row; roadmap rows change only when a probe passes',
  'the Rollback header of migrations/2026-11-05-roadmap-built-verify.sql',
  'built roadmap items reach verified by their own probe and their mirrors close without a session',
  'roadmap mirrors open over 3 days with merged code fall from 24 toward 0', 'none', 'd1:qnfo-audit reads, curl of 6 live endpoints, node:sqlite fixture in migrations/roadmap-built-verify.test.mjs'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE action LIKE 'ROADMAP-BUILT-VERIFY-1:%');
